#include <bits/stdc++.h>
using namespace std;
const int MAXN = 577;
int n, m, Mod, dp[MAXN], dp2[MAXN], C[MAXN][MAXN], res[MAXN][MAXN], res2[MAXN][MAXN];

inline int sumRange(int left, int right) {
    return ((left + right) * 1LL * (right - left + 1) / 2) % Mod;
}

int main() {
    scanf("%d%d%d", &n, &m, &Mod);
    for (int i = 0; i < MAXN; ++i) {
        C[i][0] = 1;
        C[i][i] = 1;
    }
    for (int i = 1; i < MAXN; ++i) {
        for (int j = 1; j < i; ++j) {
            C[j][i] = (C[j][i - 1] + C[j - 1][i - 1]) % Mod;
        }
    }
    dp[0] = 1; dp2[0] = 0;
    for (int length = 1; length <= n; ++length) {
        for (int i = 1; i <= length; ++i) {
            int total = sumRange(1, i - 1) + sumRange(1, length - i);
            int count = length + 1;
            long long temp1 = (long long)dp[i - 1] * count % Mod * dp[length - i] % Mod * C[i - 1][length - 1];
            long long temp2 = (long long)total * dp[i - 1] % Mod * dp[length - i] % Mod * C[i - 1][length - 1];
            long long temp3 = (long long)dp2[i - 1] * count % Mod * dp[length - i] % Mod * C[i - 1][length - 1];
            long long temp4 = (long long)dp2[length - i] * count % Mod * dp[i - 1] % Mod * C[i - 1][length - 1];

            dp[length] = (dp[length] + temp1) % Mod;
            dp2[length] = (dp2[length] + temp2 + temp3 + temp4) % Mod;
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m && j <= i; ++j) {
            res[i][j] = res[i - 1][j];
            res2[i][j] = res2[i - 1][j];
            for (int h = 1; h < j; ++h) {
                res[i][j] = (res[i][j] + (long long)res[i - h - 1][j - h] * dp[h] % Mod * C[h][j]) % Mod;
                res2[i][j] = (res2[i][j] + (long long)res2[i - h - 1][j - h] * dp[h] % Mod * C[h][j]) % Mod;
                res2[i][j] = (res2[i][j] + (long long)res[i - h - 1][j - h] * dp2[h] % Mod * C[h][j]) % Mod;
            }
            res[i][j] = (res[i][j] + dp[j]) % Mod;
            res2[i][j] = (res2[i][j] + dp2[j]) % Mod;
        }
    }
    printf("%d\n", res2[n][m]);
    return 0;
}
